import { ProofContentType } from '../../domain';

export interface StoredProof {
  content: Uint8Array;
  contentType: ProofContentType;
}

export interface ProofStorage {
  /** @returns the key to read the file back, generated by the storage. */
  save(content: Uint8Array, contentType: ProofContentType): Promise<string>;
  /**
   * @throws ProofNotFoundError if nothing is stored under the key.
   * @throws InvalidProofKeyError if the key is not one this storage generates.
   */
  read(key: string): Promise<StoredProof>;
  /** Deleting a key that holds nothing is not an error. */
  delete(key: string): Promise<void>;
}
